import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Salary Band Import Runbook","description":"","frontmatter":{},"headers":[],"relativePath":"operations/salary-band-import.md","filePath":"operations/salary-band-import.md"}'),i={name:"operations/salary-band-import.md"};function r(s,e,d,l,p,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="salary-band-import-runbook" tabindex="-1">Salary Band Import Runbook <a class="header-anchor" href="#salary-band-import-runbook" aria-label="Permalink to &quot;Salary Band Import Runbook&quot;">​</a></h1><p>Use this runbook to turn published federal wage percentiles into a starting salary ladder for a discipline, using <code>scripts/fetch-salary-bands.js</code>.</p><p><strong>This script writes nothing.</strong> It reads a tenant&#39;s headquarters location and its disciplines&#39; occupation mappings, calls the CareerOneStop wage API, and prints the resulting ladder boundaries for a human to review and paste in — no database write, no endpoint call, no audit message. There is no &quot;apply&quot; flag.</p><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ol><li><p><strong>The tenant&#39;s HQ location must be set.</strong> In <code>/admin</code>, find the tenant row and set <strong>HQ Location</strong> (e.g. <code>Ann Arbor, MI</code>). See the tenant-shape section of <code>CLAUDE.md</code>. If it isn&#39;t set, pass <code>--location=&quot;City, ST&quot;</code> on the command line instead.</p></li><li><p><strong>At least one discipline must have an occupation code mapped.</strong> On <code>/console/disciplines</code>, open a discipline&#39;s Edit modal and pick its occupation from the grouped picker. Disciplines with no mapping are skipped and listed — never guessed at.</p></li><li><p><strong>CareerOneStop API credentials.</strong> Register for free at <a href="https://www.careeronestop.org/Developers/WebAPI/registration.aspx" target="_blank" rel="noreferrer">https://www.careeronestop.org/Developers/WebAPI/registration.aspx</a>, then set:</p><ul><li><code>CAREERONESTOP_USER_ID</code></li><li><code>CAREERONESTOP_TOKEN</code></li></ul><p>Do not commit these anywhere, and do not add them to a tenant file — they are process environment variables only.</p></li></ol><hr><h2 id="running-it" tabindex="-1">Running it <a class="header-anchor" href="#running-it" aria-label="Permalink to &quot;Running it&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node scripts/fetch-salary-bands.js --tenant=&lt;id&gt; [--location=&quot;Ann Arbor, MI&quot;] [--dry-run]</span></span></code></pre></div><ul><li><code>--tenant=&lt;id&gt;</code> — required, matches the tenants file.</li><li><code>--location=&lt;..&gt;</code> — optional; overrides the tenant&#39;s stored <code>hq_location</code> for this run only.</li><li><code>--dry-run</code> — lists which disciplines would be queried and with what location, without making any network calls or requiring API credentials. Use this to sanity-check the setup before spending an API call.</li></ul><hr><h2 id="reading-the-output" tabindex="-1">Reading the output <a class="header-anchor" href="#reading-the-output" aria-label="Permalink to &quot;Reading the output&quot;">​</a></h2><p>For each mapped discipline, the script prints:</p><ul><li>The occupation title and code it queried.</li><li><strong>Which geography tier the numbers came from</strong> — <code>metro/local</code>, <code>state</code>, or <code>national</code>. A ladder built on national numbers for a company in a small town is a legitimate answer, but you need to know that&#39;s what you&#39;re looking at before you paste it in.</li><li>The four raw wage anchors (10th, 25th, 75th, 90th percentile annual wage).</li><li>The five resulting ladder boundaries, formatted for pasting straight into the salary ladder modal on <code>/console/benchmarks</code> (floor, the three interior boundaries, ceiling).</li></ul><p>At the end, a summary line: how many disciplines produced a ladder, how many were skipped or failed, and how many had no occupation mapped at all.</p><p><strong>The published figures are a starting point, not a verdict.</strong> Some businesses deliberately pay above the local market to win talent; some pay below it and compete on other things. Treat the printed ladder as a first draft to sanity-check against your own pay strategy, not a number to paste in unquestioned.</p><hr><h2 id="why-some-disciplines-don-t-get-a-ladder" tabindex="-1">Why some disciplines don&#39;t get a ladder <a class="header-anchor" href="#why-some-disciplines-don-t-get-a-ladder" aria-label="Permalink to &quot;Why some disciplines don&#39;t get a ladder&quot;">​</a></h2><p>The script refuses rather than approximates. You&#39;ll see one of these reasons:</p><ul><li><strong>&quot;no occupation mapped&quot;</strong> — the discipline has no <code>soc_code</code> set. Set one on <code>/console/disciplines</code> and re-run.</li><li><strong>&quot;top-coded/censored value&quot;</strong> — published wage data caps very high earners at a bound (e.g. &quot;≥ $239,200&quot;) rather than a real figure. Arithmetic on a capped value is meaningless, so the script refuses that geography tier and tries the next broader one; if every tier is capped, the discipline is reported unavailable.</li><li><strong>&quot;no data published for this geography&quot;</strong> — the tier is simply empty for that occupation × location (a suppressed cell). The script falls through to the next broader tier automatically.</li><li><strong>A data-anomaly refusal</strong> (e.g. two percentiles came back equal) — the published figures for that geography don&#39;t support a valid ladder. This is reported directly; it does not fall through to a different tier, since the data existed but didn&#39;t make sense.</li><li><strong>An HTTP or network failure</strong> — reported with the status code. The script never substitutes a different geography to paper over a transport error.</li></ul><h2 id="what-the-script-never-does" tabindex="-1">What the script never does <a class="header-anchor" href="#what-the-script-never-does" aria-label="Permalink to &quot;What the script never does&quot;">​</a></h2><ul><li>It never mixes geography tiers within one ladder (no splicing a national 90th onto a local 25th).</li><li>It never treats a capped/censored figure as if it were a real number.</li><li>It never guesses an occupation for an unmapped discipline.</li><li>It never writes to the database, calls a write endpoint, or posts to the audit channel.</li></ul><h2 id="after-running-it" tabindex="-1">After running it <a class="header-anchor" href="#after-running-it" aria-label="Permalink to &quot;After running it&quot;">​</a></h2><p>Copy the five printed boundaries into the discipline&#39;s salary ladder modal on <code>/console/benchmarks</code> (owner only). Nothing changes until you do — the script&#39;s job ends at the terminal.</p>',24)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
